import{_ as a,k as i,a6 as s,j as l}from"./chunks/framework.W_BvR9CP.js";const m=JSON.parse('{"title":"v1.42.0","description":"The changelog for v1.42.0.","frontmatter":{"title":"v1.42.0","page_title":"v1.42.0 Changelog","description":"The changelog for v1.42.0.","category":"Releases","mentions":["8Crafter"]},"headers":[{"level":2,"title":"Breaking Removals","slug":"breaking-removals","link":"#breaking-removals","children":[]},{"level":2,"title":"Changes","slug":"changes","link":"#changes","children":[{"level":3,"title":"Items","slug":"items","link":"#items","children":[]},{"level":3,"title":"UIs","slug":"uis","link":"#uis","children":[]}]},{"level":2,"title":"Fixes","slug":"fixes","link":"#fixes","children":[{"level":3,"title":"UIs","slug":"uis-1","link":"#uis-1","children":[]}]},{"level":2,"title":"Technical Additions","slug":"technical-additions","link":"#technical-additions","children":[{"level":3,"title":"API","slug":"api","link":"#api","children":[]}]},{"level":2,"title":"Technical Changes","slug":"technical-changes","link":"#technical-changes","children":[{"level":3,"title":"API","slug":"api-1","link":"#api-1","children":[]}]}],"relativePath":"changelogs/v1.42.0.md","filePath":"changelogs/v1.42.0.md"}'),t={name:"changelogs/v1.42.0.md"};function n(o,e,r,c,h,d){return l(),i("div",null,e[0]||(e[0]=[s('<p><strong>Updated the add-on to 1.26.0!</strong></p><h2 id="breaking-removals" tabindex="-1">Breaking Removals <a class="header-anchor" href="#breaking-removals" aria-label="Permalink to &quot;Breaking Removals&quot;">​</a></h2><ul><li>Removed the <code class="shiki"><span>@minecraft/server-admin</span></code> module from the pack&#39;s <code class="shiki"><span>manifest.json</span></code> file, meaning to use it you will have to manually uncomment it in the <code class="shiki"><span>manifest.json</span></code> file of the behavior pack. This was done to keep the pack compatible with Realms, as Microsoft removed the ability to use the <code class="shiki"><span>@minecraft/server-admin</span></code> module on Realms 😭. <ul><li>As a result of this, the transfer players feature is no longer functional unless the module is manually uncommented in the <code class="shiki"><span>manifest.json</span></code> file of the behavior pack, this also means the transfer players feature cannot be used on Realms ever again, as the module no longer works on Realms due to Microsoft removing really good features 😭.</li></ul></li></ul><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><h3 id="items" tabindex="-1">Items <a class="header-anchor" href="#items" aria-label="Permalink to &quot;Items&quot;">​</a></h3><ul><li>The <a href="./../items/debug-screen">Debug Screen</a> is no longer available in the creative inventory as it serves no practical use as it was never actually developed and is just a crude version of the <a href="./../items/editor-stick">Editor Stick</a> (it can still be obtained through commands).</li></ul><h3 id="uis" tabindex="-1">UIs <a class="header-anchor" href="#uis" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>The &quot;8Crafter&#39;s Server Utilities &amp; Debug Sticks&quot; button on the vanilla settings menu has been renamed to &quot;8Crafter&#39;s Server Utilities&quot;.</li></ul><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><h3 id="uis-1" tabindex="-1">UIs <a class="header-anchor" href="#uis-1" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Fixed a bug where the title of the &quot;Parameters Basics&quot; section of the &quot;8Crafter&#39;s Server Utilities&quot; section of the &quot;How to Play&quot; screen had a title of <code class="shiki"><span>andexdb.commandsParametersBasics.title</span></code> instead of <code class="shiki"><span>Commands Parameters Basics</span></code>.</li></ul><h2 id="technical-additions" tabindex="-1">Technical Additions <a class="header-anchor" href="#technical-additions" aria-label="Permalink to &quot;Technical Additions&quot;">​</a></h2><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><ul><li>The following modules will now be automatically imported into the <a href="https://api.8crafter.com/andexdb/v1.42.0/modules/Globals.modules.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span></code></a> namespace if they are added into the <code class="shiki"><span>manifest.json</span></code>: <ul><li><code class="shiki"><span>@minecraft/server-graphics</span></code></li></ul></li><li>The following modules will now be automatically imported into the <a href="https://api.8crafter.com/andexdb/v1.42.0/modules/Globals.modules.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span></code></a> namespace if they are available: <ul><li><code class="shiki"><span>@minecraft/server-bindings</span></code></li><li><code class="shiki"><span>@minecraft/server-private-bindings</span></code></li><li><code class="shiki"><span>@minecraft/server-ui-bindings</span></code></li><li><code class="shiki"><span>@minecraft/server-ui-private-bindings</span></code></li></ul></li></ul><h2 id="technical-changes" tabindex="-1">Technical Changes <a class="header-anchor" href="#technical-changes" aria-label="Permalink to &quot;Technical Changes&quot;">​</a></h2><h3 id="api-1" tabindex="-1">API <a class="header-anchor" href="#api-1" aria-label="Permalink to &quot;API&quot;">​</a></h3><ul><li>Updated the <a href="https://api.8crafter.com/andexdb/v1.42.0/modules/_minecraft_vanilla-data.html" target="_blank" rel="noreferrer"><code class="shiki"><span>@minecraft/vanilla-data</span></code></a> module from <code class="shiki"><span>v1.21.120</span></code> to <code class="shiki"><span>v1.26.0</span></code>.</li></ul>',17)]))}const p=a(t,[["render",n]]);export{m as __pageData,p as default};
